type Page='owed'|'game'|'missing'|'overview'|'players'|'activity'|'settlements'|'history'|'settings'|'music';
type Modal='email'|'session'|'player'|'edit-player'|'buyin'|'cashout'|'transfer'|'close'|'notes'|'share'|'void'|'allocate'|'unlock'|'';
const formatTime=(at:string|null)=>at?new Date(at).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}):'—';
const formatDate=(at:string|null)=>at?new Date(at).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'—';
const DATED=/\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.? \d{1,2}\b/i;
const hasDate=(title:string)=>DATED.test(title);
const gameLabel=(g:any)=>hasDate(g.title)?g.title:`${g.title} · ${formatDate(gameDate(g))}`;
const sameDay=(a:string|null,b=new Date())=>!!a&&new Date(a).toDateString()===b.toDateString();
const tone=(n:number)=>n>0?'positive':n<0?'negative':'';
const duration=(g:any)=>{const start=gameDate(g);if(!start)return '—';const end=g.endedAt?Date.parse(g.endedAt):g.status==='open'?Date.now():null;if(!end)return '—';const mins=Math.max(0,Math.round((end-Date.parse(start))/60000));return mins>=60?`${Math.floor(mins/60)}h ${mins%60}m`:`${mins}m`;};
function download(filename:string,body:string,type='application/json'){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export default function OpenStaxPoker(){
 const {data,ready,online,pending,saving,updatedAt,error,clearError,dispatch,retry}=useLedger();
 const initialRoute=typeof window!=='undefined'?readRoute(window.location.pathname):readRoute('/');
 const [page,setPage]=useState<Page>(()=>typeof window!=='undefined'&&(new URLSearchParams(window.location.search).has('code')||new URLSearchParams(window.location.search).has('error'))?'music':initialRoute.page as Page),[sessionId,setSessionId]=useState(initialRoute.sessionId),[modal,setModal]=useState<Modal>(''),[preset,setPreset]=useState<any>({}),[formError,setFormError]=useState(''),[notice,setNotice]=useState<{text:string,error?:boolean}|null>(null),[query,setQuery]=useState(''),[filter,setFilter]=useState('all'),[selectedPlayer,setSelectedPlayer]=useState('');
 const [gameFilter,setGameFilter]=useState('all'),[methodFilter,setMethodFilter]=useState('all'),[summaryId,setSummaryId]=useState(''),[pickedGame,setPickedGame]=useState(''),[historyQuery,setHistoryQuery]=useState('');
 const [cashier,setCashier]=useState({type:'buyin',playerId:'',amount:'',method:'Cash',newName:'',cashUp:false,heldBy:'',makeBanker:true});
 const [statusFilter,setStatusFilter]=useState('all');
 const [motion,setMotion]=useState(()=>{if(typeof window==='undefined')return false;try{return !window.matchMedia('(prefers-reduced-motion: reduce)').matches&&localStorage.getItem('felt-club.motion')!=='off';}catch{return false;}});
 const [intro,setIntro]=useState(shouldPlayIntro);const videoRef=useRef<HTMLVideoElement>(null);
 useEffect(()=>{try{localStorage.setItem('felt-club.motion',motion?'on':'off');}catch{}const v=videoRef.current;if(v){if(motion)void v.play().catch(()=>{});else v.pause();}},[motion]);
 useEffect(()=>{const preference=window.matchMedia('(prefers-reduced-motion: reduce)');const changed=()=>{if(preference.matches)setMotion(false);};preference.addEventListener('change',changed);return()=>preference.removeEventListener('change',changed);},[]);
 // Lay out against the 1672x941 design canvas and scale the whole interface to the window.
 useEffect(()=>{const fit=()=>{const w=window.innerWidth,h=window.innerHeight,scale=w>=1100?Math.min(1.6,Math.max(.72,Math.min(w/1672,h/941))):1,root=document.documentElement;root.style.setProperty('--ui-scale',String(scale));root.style.setProperty('--vh',`${h/scale}px`);};fit();window.addEventListener('resize',fit);return()=>window.removeEventListener('resize',fit);},[]);
 const [editor,setEditor]=useState(false);const editorRef=useRef(false),afterUnlock=useRef<any>(null);
 const fileRef=useRef<HTMLInputElement>(null),dialogRef=useRef<HTMLDialogElement>(null),returnFocus=useRef<HTMLElement|null>(null);
 const s=sessionId?data.sessions.find((x:any)=>x.id===sessionId):data.sessions.at(-1),st=s?stats(s):null,ids=s?participants(s):[];
 const debts=outstandingDebts(data),debtors=[...debts].map(([id,items]:any)=>({id,items,total:items.reduce((n:number,d:any)=>n+d.amount,0)})).sort((a:any,b:any)=>b.total-a.total);
 const unpaidRows=debtors.flatMap((d:any)=>d.items.map((t:any)=>({...t,from:d.id}))),unpaidTotal=debtors.reduce((n:number,d:any)=>n+d.total,0);
 const liveGame=[...data.sessions].reverse().find((g:any)=>g.status==='open');
 const music=useMusic(s?.id,editor);
 const privateProfiles=usePlayerContacts(editor);
 useEffect(()=>{if(editor)void deliverQueuedEmails().catch(()=>{});},[editor]);
 const person=(id:string)=>id===BANK_ID?(s?.mode==='decentralized'?'Table pot':'Bank'):data.players.find((x:any)=>x.id===id)?.name||'Unknown player';
 const indexOf=(id:string)=>data.players.findIndex((p:any)=>p.id===id);
 const who=(id:string,small=true)=><Who name={person(id)} index={indexOf(id)} small={small}/>;
 const open=(type:Modal,values:any={})=>{if(type&&type!=='share'&&type!=='unlock'&&!editorRef.current){afterUnlock.current={modal:type,preset:values};type='unlock';}returnFocus.current=document.activeElement as HTMLElement;setPreset(values);setSelectedPlayer(values.playerId||'');setFormError('');setModal(type);};
 useEffect(()=>{void apiFetch('/api/access').then(r=>r.json()).then((v:any)=>{setEditor(v.editor);editorRef.current=v.editor;}).catch(()=>{});const unlock=()=>{setEditor(false);editorRef.current=false;setModal('unlock');};window.addEventListener('pokerbank:unlock',unlock);return()=>window.removeEventListener('pokerbank:unlock',unlock);},[]);
 const toast=(text:string,error=false)=>{setNotice({text,error});};
 useEffect(()=>{if(notice){const timer=setTimeout(()=>setNotice(null),5000);return()=>clearTimeout(timer);}},[notice]);
 useEffect(()=>{if(modal&&!dialogRef.current?.open){dialogRef.current?.showModal();}if(!modal&&dialogRef.current?.open){dialogRef.current.close();returnFocus.current?.focus();}},[modal]);
 useEffect(()=>{const listener=(e:KeyboardEvent)=>{if(e.ctrlKey||e.metaKey||e.altKey||modal||['INPUT','TEXTAREA','SELECT'].includes((e.target as HTMLElement)?.tagName))return;if(e.key.toLowerCase()==='b'&&s?.status==='open'){e.preventDefault();open('buyin');}if(e.key.toLowerCase()==='n'){e.preventDefault();open('session');}};window.addEventListener('keydown',listener);return()=>window.removeEventListener('keydown',listener);},[modal,s]);
 const act=(type:string,payload:any,message?:string)=>{if(!editorRef.current){afterUnlock.current={action:type,payload,message};open('unlock');return null;}try{const id=dispatch(type,payload);if(message)toast(message);return id;}catch(e){const text=e instanceof Error?e.message:'Something went wrong.';if(modal)setFormError(text);else toast(text,true);return null;}};
 const go=(p:Page,id='')=>{const path=routePath(p,id);window.history.pushState({},'',path);setPage(p);setSessionId(id);setQuery('');setFilter('all');window.scrollTo({top:0,behavior:'instant'});};
 const navigate=(p:Page)=>{if(['game','activity','settlements'].includes(p)){if(s)go(p,s.id);else go('history');}else go(p);};
 const selectGame=(id:string,tab:'game'|'settlements'|'activity'='game')=>go(tab,id);
 const link=(p:Page,id='')=>({href:routePath(p,id),onClick:(e:React.MouseEvent)=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();id?go(p,id):navigate(p);}});
 useEffect(()=>{const pop=()=>{const route=readRoute(window.location.pathname);setPage(route.page as Page);setSessionId(route.sessionId);setQuery('');setFilter('all');};window.addEventListener('popstate',pop);return()=>window.removeEventListener('popstate',pop);},[]);
 useEffect(()=>{document.title=`${page==='game'&&s?s.title:page==='overview'?'Dashboard':page==='history'?'Games':page==='owed'?'Settlements':page.charAt(0).toUpperCase()+page.slice(1)} · OpenStax Poker`;},[page,s]);
 const exportJSON=()=>download(`openstax-poker-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(data,null,2));
 const exportCSV=()=>{
  if(!s)return;const cell=(v:any)=>{let value=String(v??'');if(/^[\s]*[=+@\-\t\r]/.test(value))value="'"+value;return '"'+value.replace(/"/g,'""')+'"';};
  const rows=[['Session','Timestamp','Type','Player','From','To','Amount USD','Method','Status','Note','Voided']];
  for(const e of s.entries)rows.push([s.title,e.at||'',e.type,e.playerId?person(e.playerId):'',e.from?person(e.from):'',e.to?person(e.to):'',(e.amount/100).toFixed(2),e.method||'',e.status||'',e.note||'',e.voidedAt||'']);
  for(const a of s.adjustments)rows.push([s.title,a.at||'','adjustment',person(a.playerId),'','',(a.amount/100).toFixed(2),'','',a.note||'',a.voidedAt||'']);
  download(`openstax-poker-${s.id}.csv`,'﻿'+rows.map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv');
 };
 async function importFile(file:File){try{const ledger=JSON.parse(await file.text());if(act('import',{ledger},'Backup imported.'))navigate('overview');}catch(e){toast(e instanceof Error?e.message:'Could not read that backup.',true);}}
 async function submit(event:React.FormEvent<HTMLFormElement>){
  event.preventDefault();setFormError('');const values=Object.fromEntries(new FormData(event.currentTarget).entries()) as any;let type:string=modal,payload:any={...values,sessionId:s?.id};
  if(modal==='unlock'){try{const response=await apiFetch('/api/access',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({passcode:values.passcode})});const result:any=await response.json();if(!response.ok){setFormError(result.error);return;}if(result.token)setEditorToken(result.token);setEditor(true);editorRef.current=true;setFormError('');setModal('');toast('Editing unlocked.');const next=afterUnlock.current;afterUnlock.current=null;if(next?.modal){setPreset(next.preset);setSelectedPlayer(next.preset?.playerId||'');setModal(next.modal);}if(next?.action)act(next.action,next.payload,next.message);void retry();}catch{setFormError('Could not connect. Please try again.');}return;}
  if(modal==='email'){const playerIds=new FormData(event.currentTarget).getAll('playerIds').map(String);if(!playerIds.length){setFormError('Choose at least one player with an email address.');return;}type='send-update';payload={sessionId:s?.id,playerIds};}
  if(modal==='session'){type='create-session';}
  if(modal==='player')type='add-player';
  if(modal==='edit-player'){if(!privateProfiles.ready){setFormError(privateProfiles.error||'Email addresses are still loading. Try again in a moment.');return;}payload.playerId=preset.playerId;}
  if(modal==='player'||modal==='edit-player')payload.emailEnabled=values.emailEnabled==='on';
  if(modal==='buyin'||modal==='cashout'){
   if(values.playerId==='__new'){
    const newId=act('add-player',{name:values.newName});if(!newId)return;payload.playerId=newId;
   }
   payload.received=values.received==='on';
  }
  if(modal==='transfer'){payload.paid=values.paid==='on';}
  if(modal==='close')type='close-session';
  if(modal==='void'){type='void-entry';payload.entryId=preset.entryId;payload.sessionId=preset.sessionId||s?.id;}
  const actionId=act(type,payload,modal==='email'?`Emails queued for ${payload.playerIds.length} player${payload.playerIds.length===1?'':'s'}.`:modal==='session'?'Game created.':modal==='buyin'?'Buy-in recorded.':modal==='cashout'?'Cash-out recorded.':modal==='transfer'?'Payment recorded.':'Saved.');if(actionId){setModal('');if(modal==='session')selectGame(actionId);if(modal==='close')navigate('settlements');}
 }
 function recordCashier(event:React.FormEvent){
  event.preventDefault();if(!s)return;let playerId=cashier.playerId;
  if(playerId==='__new'){const id=act('add-player',{name:cashier.newName});if(!id)return;playerId=id;}
  const heldBy=cashier.heldBy||s.bankers?.[playerId]||'';
  const id=act(cashier.type,{sessionId:s.id,playerId,amount:cashier.amount,method:cashier.method,received:true,note:'',...(cashier.type==='buyin'&&cashier.cashUp?{cashUpfront:true,heldBy,makeBanker:cashier.makeBanker}:{})},cashier.type==='buyin'?`Buy-in recorded for ${person(playerId)}.`:`Cash-out recorded for ${person(playerId)}.`);
  if(id)setCashier({...cashier,playerId:'',amount:'',newName:'',cashUp:false,heldBy:''});
 }
 const settle=(gameId:string,from:string,to:string,amount:number,method='Other')=>act('transfer',{sessionId:gameId,from,to,amount:(amount/100).toFixed(2),method,paid:true,note:''},`${person(from)} → ${person(to)} marked paid.`);
 function remind(ids:string[]){if(privateProfiles.ready){const missing=ids.filter(id=>!privateProfiles.contacts[id]?.email||privateProfiles.contacts[id]?.enabled===false);if(missing.length===ids.length){toast(`No email saved for ${missing.map(person).join(', ')}.`,true);return;}ids=ids.filter(id=>!missing.includes(id));}act('send-reminders',{playerIds:ids},`Reminder sent to ${ids.map(person).join(', ')}.`);}
 const syncLabel=!online?(pending?`${pending} change${pending===1?'':'s'} waiting`:'Offline'):saving?'Saving…':pending?`${pending} change${pending===1?'':'s'} queued`:ready?'All changes saved':'Connecting…';
 const allSaved=online&&ready&&!saving&&!pending;
 const lock=()=>void apiFetch('/api/access',{method:'DELETE'}).then(()=>{setEditorToken(null);setEditor(false);editorRef.current=false;toast('Editing locked.');});
 const entryStatus=(e:any)=>{const deferred=e.type==='buyin'&&e.status!=='received'&&data.sessions.find((g:any)=>g.entries.includes(e))?.mode==='decentralized';return e.voidedAt?<Pill kind="closed">Voided</Pill>:deferred?<Pill kind="pending">Due at end</Pill>:e.type==='cashout'?<Pill kind="closed">Counted</Pill>:e.status==='received'?<Pill kind="paid">Received</Pill>:e.status==='paid'?<Pill kind="paid">Paid</Pill>:<Pill kind="pending">Pending</Pill>;};
 const gameDebt=(g:any)=>unpaidRows.filter((t:any)=>t.game.id===g.id).reduce((n:number,t:any)=>n+t.amount,0);
 const gameStatus=(g:any)=>g.status==='open'?<Pill kind="open">Open</Pill>:stats(g).unresolved||gameDebt(g)?<Pill kind="unsettled">Unsettled</Pill>:<Pill kind="closed">Closed</Pill>;
 const reviewGames=data.sessions.filter((g:any)=>g.status==='closed'&&stats(g).unresolved!==0),chipDifference=reviewGames.reduce((n:number,g:any)=>n+Math.abs(stats(g).unresolved),0);
 const differenceCard=<StatCard icon={Landmark} label="Chip Difference" value={money(chipDifference)} tone={chipDifference?'down':'up'} sub={reviewGames.length?`${reviewGames.length} game${reviewGames.length===1?'':'s'} to review`:'All counts balance'} onClick={reviewGames.length?()=>selectGame(reviewGames[0].id,'settlements'):undefined}/>;

 function Register({entries,full=true}:{entries:any[],full?:boolean}){return <div className="scroll"><table><thead><tr><th>Time</th><th>Player</th><th>Type</th><th className="num">Amount</th><th>Method</th><th>Status</th>{full&&<><th>Notes</th><th/></>}</tr></thead><tbody>{entries.length?entries.map(e=>{
  const isBuy=e.type==='buyin',deferred=isBuy&&s?.mode==='decentralized'&&e.status!=='received';
  return <tr key={e.id} className={e.voidedAt?'voided':''}><td>{formatTime(e.at)}</td><td>{e.type==='transfer'?<span className="who">{who(e.from)}<ArrowRight className="arrow" size={14}/>{who(e.to)}</span>:who(e.playerId)}</td><td>{isBuy?'Buy-in':e.type==='cashout'?'Cash-out':'Payment'}</td><td className="num amt">{money(e.amount)}</td><td><Method method={e.method}/></td><td>{entryStatus(e)}</td>{full&&<><td className="muted">{e.note||'—'}</td><td className="act">{!e.voidedAt&&<span className="btn-row">{e.type==='transfer'&&e.status==='pending'&&<button className="btn small settle" onClick={()=>act('confirm-entry',{sessionId:s.id,entryId:e.id},'Payment confirmed.')}><Check size={14}/>Paid</button>}{isBuy&&!deferred&&e.status==='pending'&&<button className="btn small settle" onClick={()=>act('confirm-entry',{sessionId:s.id,entryId:e.id},'Buy-in received.')}><Check size={14}/>Received</button>}<button className="dots" title="Void entry" aria-label="Void entry" onClick={()=>open('void',{entryId:e.id})}><RotateCcw size={15}/></button></span>}</td></>}</tr>;
 }):<tr><td className="empty" colSpan={full?8:6}>No transactions yet.</td></tr>}</tbody></table></div>;}

 function GameSummary({game,picker=false,action}:{game:any,picker?:boolean,action?:React.ReactNode}){
  const g=game?stats(game):null,people=game?participants(game):[],owed=game?gameDebt(game):0,payments=game?unpaidRows.filter((t:any)=>t.game.id===game.id).length:0;
  return <section className="box"><div className="box-title"><h2>Game Summary</h2>{picker&&<select aria-label="Choose game" value={game?.id||''} onChange={e=>setSummaryId(e.target.value)}>{[...data.sessions].reverse().map((x:any)=><option key={x.id} value={x.id}>{gameLabel(x)}</option>)}</select>}</div>
   {game?<><div className="summary-art"/><div className="summary-rows">
    <div className="summary-row"><Landmark size={22}/><span>{game.mode==='centralized'?'Banker':'Settlement'}</span><small>{game.mode==='centralized'?'Banker collects':'Pay at end'}</small><strong>{gameStatus(game)}</strong></div>
    <div className="summary-row"><Coins size={22}/><span>Buy-ins</span><small>{people.length} players</small><strong>{money(g!.totalIn)}</strong></div>
    <div className="summary-row"><LogOut size={22}/><span>Cash-outs</span><small>{people.filter((id:any)=>!playerStats(game,id).open).length} players</small><strong>{money(g!.totalOut)}</strong></div>
    <div className="summary-row emph"><Clock size={22}/><span>Outstanding</span><small>{payments} payment{payments===1?'':'s'}</small><strong>{money(owed)}</strong></div>
    <div className="summary-row"><Landmark size={22}/><span>Difference</span><small>{game.status==='open'?'Game in progress':g!.unresolved?'Needs review':'Balanced'}</small><strong className={g!.unresolved?'negative':'positive'}>{money(g!.unresolved)}</strong></div>
   </div>{action&&<div className="box-body">{action}</div>}</>:<p className="empty-note">No games yet.</p>}
  </section>;
 }

 function GameBar(){return <div className="game-bar">
  <div className="game-chip">{s.status==='open'&&<span className="live-chip" style={{padding:0,border:0,background:'none'}}><i className="dot"/></span>}<div><h1>{s.title}</h1><small>{!hasDate(s.title)&&<>{formatDate(gameDate(s))} · </>}{s.mode==='centralized'?'Banker collects':'Pay at end'} · {duration(s)}</small></div>{gameStatus(s)}</div>
  <nav className="segmented" aria-label="Game navigation">{[{id:'game',label:'Table'},{id:'activity',label:'Activity'},{id:'settlements',label:'Settlements'}].map(tab=><a key={tab.id} className={page===tab.id?'active':''} {...link(tab.id as Page,s.id)}>{tab.label}</a>)}</nav>
  <span className="spacer"/>
  <label className="filter">Game<select aria-label="Choose game" value={s.id} onChange={e=>selectGame(e.target.value,page as any)}>{[...data.sessions].reverse().map((x:any)=><option key={x.id} value={x.id}>{x.title}</option>)}</select></label>
  <button className="btn" onClick={()=>open('notes')}><NotebookPen size={16}/>Notes</button>
  <button className="btn" onClick={exportCSV}><Download size={16}/>Export</button>
  {s.status==='open'?<button className="btn settle" onClick={()=>open('close')}><Flag size={16}/>Close game</button>:<button className="btn" onClick={()=>act('reopen-session',{sessionId:s.id},'Game reopened.')}><RotateCcw size={16}/>Reopen</button>}
 </div>;}

 function DashboardPage(){
  const a=ledgerAnalytics(data),recent=[...data.sessions].reverse(),openGames=recent.filter((g:any)=>g.status==='open');
  const events=data.sessions.flatMap((g:any)=>[...(g.createdAt?[{at:g.createdAt,kind:'start',game:g}]:[]),...(g.endedAt?[{at:g.endedAt,kind:'close',game:g}]:[]),...g.entries.filter((e:any)=>!e.voidedAt&&e.at&&(e.type!=='transfer'||e.status==='paid')).map((e:any)=>({at:e.at,kind:e.type,e,game:g}))]).sort((x:any,y:any)=>y.at.localeCompare(x.at)).slice(0,30);
  const live=liveGame,liveIds=live?participants(live):[];
  const when=(at:string)=>sameDay(at)?formatTime(at):`${new Date(at).toLocaleDateString('en-US',{month:'short',day:'numeric'})}, ${formatTime(at)}`;
  const settleAll=()=>{if(!unpaidRows.length||!confirm(`Mark all ${unpaidRows.length} payments (${money(unpaidTotal)}) as paid?`))return;for(const t of unpaidRows)settle(t.game.id,t.from,t.to,t.amount,t.method);};
  const showMethod=unpaidRows.some((t:any)=>t.method);
  return <div className="dash">
  <div className="stats">
   <StatCard icon={Users} label="Open Games" value={openGames.length} sub={`${a.completed} closed · ${data.sessions.length} total`} onClick={()=>navigate('history')}/>
   <StatCard icon={FileText} label="Unpaid Settlements" value={unpaidRows.length} sub={`${money(unpaidTotal)} total`} onClick={()=>navigate('owed')} view/>
   <StatCard icon={Coins} label="Outstanding" value={money(unpaidTotal)} sub={`Across ${debtors.length} player${debtors.length===1?'':'s'}`} onClick={()=>navigate('owed')} view/>
   {differenceCard}
  </div>
  <div className="grid-main">
   <section className="box"><div className="box-title"><h2>Current Table{live&&<><Pill kind="playing">Live</Pill><span className="title-meta">{live.title}<i/>{live.mode==='centralized'?'Banker collects':'Pay at end'}</span></>}</h2><div className="tools">{live?<><span className="meta"><Clock size={14}/>{duration(live)}</span><button className="btn small" onClick={()=>selectGame(live.id)}><SettingsIcon size={15}/>Manage Game</button></>:<button className="btn gold small" onClick={()=>open('session')}><Plus size={15}/>New game</button>}</div></div>
    <PokerTable seats={liveIds.map((id:any)=>{const p=playerStats(live,id);return {id,name:person(id),index:indexOf(id),amount:p.open?p.bought:p.cashed,out:!p.open};})} title={live?live.title:'No game running'} subtitle={live?undefined:'Start a game to seat players'} total={live?stats(live).totalIn-stats(live).adjusted:0} totalLabel="In play" onSeat={id=>live&&open('buyin',{playerId:id})}/>
   </section>
   <section className="box"><div className="box-title"><h2>Settlement Queue{unpaidRows.length>0&&<span className="count-pill">{unpaidRows.length} Unpaid</span>}</h2><a className="link" {...link('owed')}>View All <ArrowRight size={15}/></a></div>
    <div className="scroll"><table><thead><tr><th>From</th><th>To</th><th className="num">Amount</th>{showMethod&&<th>Method</th>}<th>Status</th><th>Action</th></tr></thead><tbody>{unpaidRows.length?unpaidRows.map((t:any)=><tr key={`${t.game.id}-${t.from}-${t.to}-${t.method||''}`}><td>{who(t.from)}</td><td>{who(t.to)}</td><td className="num amt">{money(t.amount)}</td>{showMethod&&<td>{t.method?<Method method={t.method}/>:<span className="muted">Any</span>}</td>}<td><Pill kind="unpaid">Unpaid</Pill></td><td className="act"><button className="btn small settle" onClick={()=>settle(t.game.id,t.from,t.to,t.amount,t.method)}>Settle</button></td></tr>):<tr><td className="empty" colSpan={6}>Nobody owes anything.</td></tr>}</tbody></table></div>
    <div className="box-foot"><span className="total"><Coins size={28}/><span><small>Total Outstanding</small><strong>{money(unpaidTotal)}</strong><em>{unpaidRows.length} settlement{unpaidRows.length===1?'':'s'}</em></span></span><button className="btn green" disabled={!unpaidRows.length} onClick={settleAll}>Settle All</button></div>
   </section>
  </div>
  <div className="grid-main">
   <section className="box"><div className="box-title"><h2>Recent Games</h2><a className="link" {...link('history')}>View All <ArrowRight size={15}/></a></div><div className="scroll"><table><thead><tr><th>Date</th><th>Game</th><th>Duration</th><th className="num">Players</th><th className="num">Buy-ins</th><th className="num">Cash-outs</th><th>Status</th></tr></thead><tbody>
    {recent.length?recent.map((g:any)=>{const t=stats(g);return <tr key={g.id} className="clickable" onClick={()=>selectGame(g.id)}><td>{formatDate(gameDate(g))}</td><td>{g.title}</td><td>{duration(g)}</td><td className="num">{participants(g).length}</td><td className="num">{money(t.totalIn)}</td><td className="num">{money(t.totalOut)}</td><td>{gameStatus(g)}</td></tr>;}):<tr><td className="empty" colSpan={7}>No games yet.</td></tr>}
   </tbody></table></div></section>
   <section className="box"><div className="box-title"><h2>Recent Activity</h2>{s&&<a className="link" {...link('activity',s.id)}>View All <ArrowRight size={15}/></a>}</div><div className="scroll"><table><thead><tr><th>Time</th><th>Event</th><th>Details</th></tr></thead><tbody>
    {events.length?events.map((v:any,i:number)=><tr key={i}><td className="muted">{when(v.at)}</td><td>{v.kind==='start'?<span className="event"><Play size={15} fill="currentColor"/>Game started</span>:v.kind==='close'?<span className="event close"><Flag size={15}/>Game closed</span>:v.kind==='buyin'?<span className="event"><Coins size={15}/>Buy-in recorded</span>:v.kind==='cashout'?<span className="event close"><LogOut size={15}/>Cash-out recorded</span>:<span className="event pay"><CheckCircle2 size={15}/>Settlement recorded</span>}</td><td>{v.kind==='start'||v.kind==='close'?v.game.title:v.kind==='transfer'?<>{person(v.e.from)} → {person(v.e.to)} <span className="positive">{money(v.e.amount)}</span>{v.e.method&&<span className="muted"> ({v.e.method})</span>}</>:<>{person(v.e.playerId)} <span className="amt">{money(v.e.amount)}</span></>}</td></tr>):<tr><td className="empty" colSpan={3}>Nothing recorded yet.</td></tr>}
   </tbody></table></div></section>
  </div></div>;
 }

 function GamesPage(){
  const all=[...data.sessions].map((g:any,i:number)=>({g,n:i+1})).reverse(),openCount=all.filter(x=>x.g.status==='open').length,unsettled=all.filter(x=>x.g.status==='closed'&&(stats(x.g).unresolved||gameDebt(x.g))).length;
  const rows=all.filter(({g})=>(filter==='all'||(filter==='open'?g.status==='open':filter==='unsettled'?g.status==='closed'&&(stats(g).unresolved||gameDebt(g)):g.status==='closed'&&!stats(g).unresolved&&!gameDebt(g)))&&g.title.toLowerCase().includes(query.toLowerCase()));
  const picked=all.find(x=>x.g.id===pickedGame)||rows[0];
  return <>
  <div className="stats">
   <StatCard icon={Layers} label="All Games" value={all.length} onClick={()=>setFilter('all')}/>
   <StatCard icon={Play} label="Open Games" value={openCount} onClick={()=>setFilter('open')}/>
   <StatCard icon={CircleCheck} label="Closed Games" value={all.length-openCount-unsettled} onClick={()=>setFilter('closed')}/>
   <StatCard icon={Hourglass} label="Unsettled Games" value={unsettled} onClick={()=>setFilter('unsettled')}/>
  </div>
  <section className="box"><div className="box-title big"><h2>All Games</h2><div className="tools">
   <label className="filter">Status<select value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">All</option><option value="open">Open</option><option value="closed">Closed</option><option value="unsettled">Unsettled</option></select></label>
   <label className="search-field"><Search size={16}/><input aria-label="Search games" placeholder="Search games…" value={query} onChange={e=>setQuery(e.target.value)}/></label>
   <button className="btn" onClick={()=>fileRef.current?.click()}><Upload size={16}/>Import</button>
   <button className="btn gold" onClick={()=>open('session')}><Plus size={16}/>New game</button>
  </div></div>
  <div className="scroll"><table><thead><tr><th>#</th><th>Date</th><th>Game Name</th><th className="num">Players</th><th>Type</th><th className="num">Buy-Ins</th><th className="num">Cash-Outs</th><th className="num">Difference</th><th className="num">To Pay</th><th>Status</th></tr></thead><tbody>
   {rows.length?rows.map(({g,n})=>{const t=stats(g),diff=t.totalOut-t.totalIn,owed=gameDebt(g);return <tr key={g.id} className={`clickable ${picked?.g.id===g.id?'selected':''}`} onClick={()=>setPickedGame(g.id)} onDoubleClick={()=>selectGame(g.id)}><td>{n}</td><td>{formatDate(gameDate(g))} <span className="muted">&nbsp;{formatTime(gameDate(g))}</span></td><td><a {...link('game',g.id)}>{g.title}</a></td><td className="num">{participants(g).length}</td><td>{g.mode==='centralized'?'Banker':'Pay at end'}</td><td className="num">{money(t.totalIn)}</td><td className="num">{money(t.totalOut)}</td><td className={`num ${g.status==='open'?'':tone(diff)}`}>{g.status==='open'?'—':signedMoney(diff)}</td><td className="num amt">{money(owed)}</td><td>{gameStatus(g)}</td></tr>;}):<tr><td className="empty" colSpan={10}>{all.length?'No games match.':'No games yet.'}</td></tr>}
  </tbody></table></div></section>
  {picked&&(()=>{const g=picked.g,t=stats(g),diff=t.totalOut-t.totalIn;return <div className="selection-bar"><div className="sel-id"><b>#{picked.n}</b><small>{formatDate(gameDate(g))} · {formatTime(gameDate(g))}</small></div><dl><div><dt>Game</dt><dd>{g.title}</dd></div><div><dt>Players</dt><dd>{participants(g).length}</dd></div><div><dt>Buy-Ins</dt><dd>{money(t.totalIn)}</dd></div><div><dt>Cash-Outs</dt><dd>{money(t.totalOut)}</dd></div><div><dt>Difference</dt><dd className={g.status==='open'?'':tone(diff)}>{g.status==='open'?'—':signedMoney(diff)}</dd></div><div><dt>To Pay</dt><dd className="amt">{money(gameDebt(g))}</dd></div></dl><button className="btn gold" onClick={()=>selectGame(g.id)}><Play size={18} fill="currentColor"/>Open Game</button></div>;})()}
  </>;
 }

 function LiveSession(){
  const counted=ids.filter((id:any)=>!playerStats(s,id).open).length,entries=s.entries.filter((e:any)=>(filter==='all'||e.type===filter)&&(!query||[e.playerId,e.from,e.to].includes(query))).slice().reverse();
  const cashOptions=cashier.type==='buyin'?data.players:data.players.filter((p:any)=>ids.includes(p.id)&&playerStats(s,p.id).open);
  return <><GameBar/>
  <div className="grid-side live-grid"><div className="stack">
   <PokerTable seats={ids.map((id:any)=>{const p=playerStats(s,id);return {id,name:person(id),index:indexOf(id),amount:p.open?p.bought:p.cashed,out:!p.open};})} title={s.title} subtitle={`${ids.length} players · ${s.mode==='centralized'?'Banker collects':'Pay at end'}`} total={s.status==='closed'?st!.totalOut:st!.totalIn-st!.adjusted} totalLabel={s.status==='closed'?'Cashed out':'In play'} onSeat={id=>s.status==='open'&&setCashier({...cashier,playerId:id,type:playerStats(s,id).open?cashier.type:'buyin'})}/>
   <section className="box register"><div className="box-title"><h2>Transaction Register</h2><div className="tools">
    <label className="filter">Player<select value={query} onChange={e=>setQuery(e.target.value)}><option value="">All</option>{ids.map((id:any)=><option key={id} value={id}>{person(id)}</option>)}</select></label>
    <label className="filter">Type<select value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">All</option><option value="buyin">Buy-ins</option><option value="cashout">Cash-outs</option><option value="transfer">Payments</option></select></label>
    <button className="btn" onClick={exportCSV}><Download size={16}/>Export</button>
   </div></div><Register entries={entries}/></section>
  </div>
  <div className="stack">
   {s.status==='open'?<section className="box cashier"><div className="box-title"><h2>Cashier</h2></div><form className="box-body" onSubmit={recordCashier}>
    <div className="field"><span>Type</span><div className="segmented">{[['buyin','Buy-in'],['cashout','Cash-out']].map(([id,label])=><button type="button" key={id} className={cashier.type===id?'active':''} onClick={()=>setCashier({...cashier,type:id,playerId:''})}>{label}</button>)}</div></div>
    <label className="field"><span>Player</span><select required value={cashier.playerId} onChange={e=>setCashier({...cashier,playerId:e.target.value})}><option value="" disabled>Choose a player</option>{cashOptions.map((p:any)=>{const owes=cashier.type==='buyin'&&debts.get(p.id);return <option key={p.id} value={p.id} disabled={!!owes}>{p.name}{owes?` (owes ${money(owes.reduce((n:number,d:any)=>n+d.amount,0))})`:ids.includes(p.id)&&cashier.type==='buyin'?` (${money(playerStats(s,p.id).bought)} in)`:''}</option>;})}{cashier.type==='buyin'&&<option value="__new">+ New player</option>}</select></label>
    {cashier.playerId==='__new'&&<label className="field"><span>Name</span><input required maxLength={100} value={cashier.newName} onChange={e=>setCashier({...cashier,newName:e.target.value})}/></label>}
    <label className="field"><span>{cashier.type==='buyin'?'Amount':'Final chips'}</span><span className="money-field"><span>$</span><input type="number" inputMode="decimal" min={cashier.type==='cashout'?'0':'0.01'} step="0.01" required value={cashier.amount} placeholder={cashier.type==='cashout'?'0 if busted':''} onChange={e=>setCashier({...cashier,amount:e.target.value})}/></span></label>
    {cashier.type==='buyin'&&<div className="quick-amounts">{[10,20,40,100].map(n=><button type="button" key={n} onClick={()=>setCashier({...cashier,amount:String(n)})}>${n}</button>)}</div>}
    {cashier.type==='buyin'&&s.mode==='decentralized'&&<><label className="field"><span>Cash up front</span><span className="check-line"><input type="checkbox" checked={cashier.cashUp} onChange={e=>setCashier({...cashier,cashUp:e.target.checked})}/>Handed to another player</span></label>{cashier.cashUp&&<><label className="field"><span>Held by</span><select required value={cashier.heldBy||s.bankers?.[cashier.playerId]||''} onChange={e=>setCashier({...cashier,heldBy:e.target.value})}><option value="" disabled>Choose a player</option>{data.players.filter((p:any)=>p.id!==cashier.playerId).map((p:any)=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label>{cashier.playerId&&!s.bankers?.[cashier.playerId]&&<label className="field"><span/><span className="check-line"><input type="checkbox" checked={cashier.makeBanker} onChange={e=>setCashier({...cashier,makeBanker:e.target.checked})}/>Make them {cashier.playerId==='__new'?'this player':person(cashier.playerId)}’s banker</span></label>}</>}</>}
    {cashier.type==='buyin'&&s.mode==='centralized'&&<div className="field"><span>Method</span><div className="method-picks">{METHODS.map(m=><button type="button" key={m} className={cashier.method===m?'active':''} onClick={()=>setCashier({...cashier,method:m})}><Method method={m}/></button>)}</div></div>}
    <button className="btn gold wide" disabled={!cashier.playerId||cashier.amount===''||(cashier.type==='buyin'&&cashier.cashUp&&!(cashier.heldBy||s.bankers?.[cashier.playerId]))}>Record {cashier.type==='buyin'?'Buy-in':'Cash-out'}</button>
   </form></section>:<section className="box"><div className="box-title"><h2>Game closed</h2></div><div className="box-body btn-row"><button className="btn gold" onClick={()=>navigate('settlements')}>Settle up<ArrowRight size={16}/></button>{!st?.unresolved&&<button className="btn" onClick={()=>open('email')}><Mail size={16}/>Resend results</button>}</div></section>}
   <section className="box session-box"><div className="box-title"><h2>Session Details</h2><button className="btn small" onClick={()=>open('notes')}><NotebookPen size={14}/>Notes</button></div><table className="facts"><tbody>
    <tr><th>Game</th><td>{s.title}</td></tr><tr><th>Type</th><td>{s.mode==='centralized'?'Banker collects':'Pay at end'}</td></tr><tr><th>Start Time</th><td>{formatDate(gameDate(s))} · {formatTime(gameDate(s))}</td></tr><tr><th>Duration</th><td>{duration(s)}</td></tr><tr><th>Players</th><td>{ids.length}</td></tr><tr><th>Total Buy-ins</th><td>{money(st!.totalIn)}</td></tr><tr><th>Total Cash-outs</th><td className="amt">{money(st!.totalOut)} <small>({counted}/{ids.length})</small></td></tr>{(()=>{const held=s.entries.filter((e:any)=>e.type==='buyin'&&e.heldBy&&!e.voidedAt);return held.length?<tr><th>Cash Held</th><td>{[...new Set(held.map((e:any)=>e.heldBy))].map((h:any)=>`${person(h)} ${money(held.filter((e:any)=>e.heldBy===h).reduce((n:number,e:any)=>n+e.amount,0))}`).join(', ')}</td></tr>:null;})()}
    <tr><th>{s.status==='closed'?'Difference':'Chips on Table'}</th><td className={s.status==='closed'&&st!.unresolved?'negative':'amt'}>{money(s.status==='closed'?st!.unresolved:st!.totalIn-st!.adjusted)}</td></tr>
   </tbody></table>{s.notes&&<div className="box-body" style={{borderTop:'1px solid var(--line)',whiteSpace:'pre-wrap'}}>{s.notes}</div>}</section>
   <section className="box table-players"><div className="box-title"><h2>Players at Table</h2><span className="count-pill" style={{background:'rgba(255,255,255,.05)',borderColor:'var(--line-2)',color:'#d8d3c7'}}>{counted}/{ids.length} out</span></div><div className="scroll"><table className="compact"><thead><tr><th>#</th><th>Player</th><th className="num">Chips</th><th className="num">Buy-ins</th><th>Status</th></tr></thead><tbody>
    {ids.length?ids.map((id:any,i:number)=>{const p=playerStats(s,id),net=balances(s).get(id)||0;return <tr key={id} className="clickable" onClick={()=>s.status==='open'&&setCashier({...cashier,playerId:p.open?id:'',type:cashier.type})}><td>{i+1}</td><td>{who(id)}</td><td className="num amt">{p.open?'—':money(p.cashed)}</td><td className="num">{money(p.bought)}</td><td>{s.status==='closed'?(net===0?<Pill kind="paid">Settled</Pill>:net>0?<Pill kind="pending">To receive</Pill>:<Pill kind="unpaid">To pay</Pill>):p.open?<Pill kind="playing">In hand</Pill>:<span className={tone(p.net)}>{signedMoney(p.net)}</span>}</td></tr>;}):<tr><td className="empty" colSpan={5}>No buy-ins yet.</td></tr>}
   </tbody></table></div></section>
  </div></div></>;
 }

 function ActivityPage(){const entries=s.entries.filter((e:any)=>(filter==='all'||e.type===filter)&&(!query||[e.playerId,e.from,e.to].includes(query))).slice().reverse();return <><GameBar/>
  <section className="box"><div className="box-title"><h2>Transaction Register</h2><div className="tools">
   <label className="filter">Player<select value={query} onChange={e=>setQuery(e.target.value)}><option value="">All</option>{ids.map((id:any)=><option key={id} value={id}>{person(id)}</option>)}</select></label>
   <label className="filter">Type<select value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">All</option><option value="buyin">Buy-ins</option><option value="cashout">Cash-outs</option><option value="transfer">Payments</option></select></label>
   <button className="btn" onClick={exportCSV}><Download size={16}/>Export</button>
  </div></div><Register entries={entries}/></section></>;}

 function PayoutOptions(){
  const prefs=(id:string)=>s.prefs?.[id]||{cashOnly:false,canBreak:false,cash:0};
  const setPref=(id:string,patch:any)=>{const cur=prefs(id),next={cashOnly:cur.cashOnly,canBreak:cur.canBreak,cash:((cur.cash||0)/100).toFixed(2),...patch};act('set-prefs',{sessionId:s.id,playerId:id,...next},'Payout options saved.');};
  return <section className="box"><div className="box-title"><h2>Payout Options</h2></div><div className="payout"><label className="payout-unit">Smallest bill $<input key={cashUnit(s)} className="cash-input" type="number" inputMode="decimal" min="0.01" step="0.01" aria-label="Smallest cash bill" defaultValue={(cashUnit(s)/100).toFixed(2)} onBlur={e=>{const v=Math.round(Number(e.target.value)*100);if(v>0&&v!==cashUnit(s))act('set-cash-unit',{sessionId:s.id,unit:e.target.value},'Smallest bill updated.');}}/><small>Cash moves in multiples of this unless someone makes change. Use 0.01 for exact amounts.</small></label>{ids.map((id:any)=>{const pr=prefs(id),held=cashOnHand(s,id);return <div className="payout-row" key={id}><div className="payout-top"><b>{person(id)}</b><label>Banker<select aria-label={`Banker for ${person(id)}`} value={s.bankers?.[id]||''} onChange={e=>act('set-banker',{sessionId:s.id,playerId:id,holderId:e.target.value},e.target.value?`${person(e.target.value)} is now ${person(id)}’s banker.`:`${person(id)} settles on their own.`)}><option value="">Self</option>{data.players.filter((p:any)=>p.id!==id).map((p:any)=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label></div><div className="payout-bottom"><label className="check-line"><input type="checkbox" checked={!!pr.cashOnly} onChange={e=>setPref(id,{cashOnly:e.target.checked})}/>Cash only</label><label className="check-line"><input type="checkbox" checked={!!pr.canBreak} onChange={e=>setPref(id,{canBreak:e.target.checked})}/>Makes change</label><label className="check-line">Cash $<input key={`${id}-${pr.cash||0}`} className="cash-input" type="number" inputMode="decimal" min="0" step="0.01" aria-label={`Cash ${person(id)} can hand out`} defaultValue={pr.cash?(pr.cash/100).toFixed(2):''} placeholder="0.00" onBlur={e=>{if(Math.round(Number(e.target.value||0)*100)!==(pr.cash||0))setPref(id,{cash:e.target.value||'0'});}}/></label>{held!==(pr.cash||0)&&<small>{money(held)} in hand</small>}</div></div>;})}</div><p className="hint" style={{padding:'12px 20px 0'}}>A banker settles for a player, so only the banker appears in the payment plan. Cash-only players are paid from whoever has cash. The plan updates as you change these.</p></section>;}
 function GameSettlements(){
  const plan=simplify(s),pendingPayments=s.entries.filter((e:any)=>e.type==='transfer'&&e.status==='pending'&&!e.voidedAt),difference=st!.unresolved,unresolved=s.status==='closed'&&difference!==0;
  const waiting=s.status==='open'&&s.mode==='decentralized',remaining=ids.filter((id:any)=>playerStats(s,id).open);
  const done=s.entries.filter((e:any)=>e.type==='transfer'&&e.status==='paid'&&!e.voidedAt).slice().reverse();
  const behalf=(id:string)=>{const deps=dependentsOf(s,id);return deps.length?<small className="sub-line">settling for {deps.map(person).join(', ')}</small>:null;};
  return <><GameBar/><div className="grid-side"><div className="stack">
   {unresolved&&<div className="notice" style={{marginBottom:0}}><AlertCircle size={20}/><div><b>Chip counts are off by {money(difference)}.</b> Fix the ledger, or record how the table agreed to split it.<div className="btn-row" style={{marginTop:10}}><button className="btn small" onClick={()=>open('allocate')}>Assign to a player</button><button className="btn small" onClick={()=>{if(confirm('Split the difference equally across all players?'))act('split-variance',{sessionId:s.id},'Difference split equally.');}}>Split equally</button>{s.mode==='centralized'&&<button className="btn small" onClick={()=>{if(confirm('Assign the difference to the bank?'))act('split-variance',{sessionId:s.id,mode:'bank'},'Difference assigned to bank.');}}>Assign to bank</button>}</div></div></div>}
   {waiting?<section className="box"><div className="box-title"><h2>Final Chip Counts<span className="count-pill" style={{background:'rgba(255,255,255,.05)',borderColor:'var(--line-2)',color:'#d8d3c7'}}>{ids.length-remaining.length} / {ids.length}</span></h2><button className="btn gold" disabled={!!remaining.length} onClick={()=>open('close')}><Flag size={16}/>Close game</button></div><div className="scroll"><table><thead><tr><th>Player</th><th className="num">Bought in</th><th className="num">Final chips</th><th/></tr></thead><tbody>{ids.map((id:any)=>{const p=playerStats(s,id);return <tr key={id}><td>{who(id)}</td><td className="num">{money(p.bought)}</td><td className="num amt">{p.open?'—':money(p.cashed)}</td><td className="act">{p.open?<button className="btn small settle" onClick={()=>open('cashout',{playerId:id})}>Cash out</button>:<Pill kind="paid">Counted</Pill>}</td></tr>;})}</tbody></table></div></section>
   :<section className="box"><div className="box-title"><h2>Settlements{plan.length>0&&<span className="count-pill">{plan.length} Unpaid</span>}{!plan.length&&!pendingPayments.length&&!unresolved&&done.length>0&&<Pill kind="paid"><Check size={12}/>All settled</Pill>}</h2><div className="tools"><button className="btn small" onClick={async()=>{try{await navigator.clipboard.writeText(`${s.title}\n${plan.map((p:any)=>`${person(p.from)} → ${person(p.to)}: ${money(p.amount)}${p.method?' (cash)':''}`).join('\n')||'All settled.'}`);toast('Payment list copied.');}catch{toast('Could not copy.',true);}}}><Copy size={14}/>Copy list</button><button className="btn gold small" onClick={()=>open('transfer')}><Plus size={14}/>Record Settlement</button></div></div>
    {plan.some((p:any)=>p.short)&&<div className="notice" style={{margin:'14px 16px 0'}}><AlertCircle size={18}/><span>Some cash-only players can’t be fully paid in cash with the cash available. Add cash on hand, or mark someone who can make change, under Payout Options.</span></div>}
    <div className="scroll"><table><thead><tr><th>From</th><th>To</th><th className="num">Amount</th><th>Method</th><th>Status</th><th/></tr></thead><tbody>{plan.map((p:any)=><tr key={`${p.from}-${p.to}-${p.method||''}`}><td>{who(p.from)}{behalf(p.from)}</td><td>{who(p.to)}</td><td className="num amt">{money(p.amount)}</td><td>{p.method?<Method method={p.method}/>:<span className="muted">Any</span>}{p.short&&<small className="sub-line negative">needs cash</small>}</td><td><Pill kind="unpaid">Unpaid</Pill></td><td className="act"><button className="btn small settle" disabled={unresolved} onClick={()=>settle(s.id,p.from,p.to,p.amount,p.method)}>Settle</button></td></tr>)}{done.map((e:any)=><tr key={e.id} className="done"><td>{who(e.from)}</td><td>{who(e.to)}</td><td className="num amt">{money(e.amount)}</td><td><Method method={e.method}/></td><td><Pill kind="paid"><Check size={12}/>Settled</Pill><small className="sub-line">{formatDate(e.confirmedAt||e.at)}</small></td><td className="act"><button className="link" onClick={()=>open('void',{entryId:e.id})}>Undo</button></td></tr>)}{!plan.length&&!done.length&&<tr><td className="empty" colSpan={6}>{pendingPayments.length?'Waiting on confirmations below.':unresolved?'Resolve the chip difference first.':'Nothing to settle.'}</td></tr>}</tbody></table></div></section>}
   {pendingPayments.length>0&&<section className="box"><div className="box-title"><h2>Awaiting Confirmation<span className="count-pill">{pendingPayments.length}</span></h2></div><Register entries={pendingPayments}/></section>}
   {s.adjustments.filter((a:any)=>!a.voidedAt).length>0&&<section className="box"><div className="box-title"><h2>Adjustments</h2></div><table><thead><tr><th>Player</th><th>Reason</th><th className="num">Amount</th><th/></tr></thead><tbody>{s.adjustments.filter((a:any)=>!a.voidedAt).map((a:any)=><tr key={a.id}><td>{who(a.playerId)}</td><td>{a.note}</td><td className={`num ${tone(a.amount)}`}>{signedMoney(a.amount)}</td><td className="act"><button className="btn small" onClick={()=>act('undo-allocation',{sessionId:s.id,allocationId:a.id},'Adjustment undone.')}>Undo</button></td></tr>)}</tbody></table></section>}
   {!waiting&&<details className="math"><summary>Show the math</summary><section className="box"><div className="scroll"><table className="compact"><thead><tr><th>Player</th><th className="num">Final chips</th><th className="num">Buy-ins</th><th className="num">Adjust.</th><th className="num">Buy-ins paid</th><th className="num">Sent − received</th><th className="num">Balance</th><th className="num">Pending</th><th className="num">After pending</th></tr></thead><tbody>{ids.map((id:any)=>{const c=balanceCalculation(s,id);return <tr key={id}><td>{person(id)}</td><td className="num">{money(c.cashed)}</td><td className="num">{money(c.bought)}</td><td className="num">{signedMoney(c.adjustment)}</td><td className="num">{money(c.paidIn)}</td><td className="num">{signedMoney(c.confirmed)}</td><td className={`num ${tone(c.balance)}`}>{signedMoney(c.balance)}</td><td className="num">{signedMoney(c.pending)}</td><td className="num">{signedMoney(c.plannedBalance)}</td></tr>;})}{(balances(s).get(BANK_ID)||0)!==0&&<tr><td>{person(BANK_ID)}</td><td colSpan={5}/><td className="num">{signedMoney(balances(s).get(BANK_ID)||0)}</td><td className="num">{signedMoney(balanceCalculation(s,BANK_ID).pending)}</td><td className="num">{signedMoney(balanceCalculation(s,BANK_ID).plannedBalance)}</td></tr>}</tbody></table></div><p className="hint" style={{padding:'12px 20px 0'}}>Balance = final chips − buy-ins + adjustments + buy-ins paid + sent − received. Payments match the largest debt with the largest credit:</p><ol className="steps">{settlementSteps(s).map((step:any,i:number)=><li key={i}>{person(step.from)} pays {person(step.to)} {money(step.amount)} <small>(owed {money(step.owedBefore)}, due {money(step.dueBefore)})</small></li>)}</ol></section></details>}
  </div>
  <div className="stack"><GameSummary game={s} action={<div className="btn-row">{s.status==='closed'&&!unresolved&&<button className="btn" onClick={()=>open('email')}><Mail size={16}/>Resend results</button>}<button className="btn" onClick={()=>open('transfer')}><Plus size={16}/>Other payment</button></div>}/>{PayoutOptions()}</div>
  </div></>;
 }

 function SettlementsPage(){
  const rows=statusFilter==='paid'?[]:unpaidRows.filter((t:any)=>gameFilter==='all'||t.game.id===gameFilter),games=[...data.sessions].reverse() as any[];
  const doneRows=(statusFilter==='unpaid'?[]:data.sessions.filter((g:any)=>gameFilter==='all'||g.id===gameFilter).flatMap((g:any)=>g.entries.filter((e:any)=>e.type==='transfer'&&e.status==='paid'&&!e.voidedAt).map((e:any)=>({e,g})))).sort((x:any,y:any)=>(y.e.confirmedAt||y.e.at||'').localeCompare(x.e.confirmedAt||x.e.at||'')).slice(0,40);
  const paid=data.sessions.flatMap((g:any)=>g.entries.filter((e:any)=>e.type==='transfer'&&!e.voidedAt).map((e:any)=>({e,g}))).sort((x:any,y:any)=>(y.e.at||'').localeCompare(x.e.at||''));
  const paidToday=paid.filter(({e}:any)=>e.status==='paid'&&sameDay(e.confirmedAt||e.at));
  const history=paid.filter(({e,g}:any)=>(historyQuery===''||[e.from,e.to].some((id:string)=>person(id).toLowerCase().includes(historyQuery.toLowerCase())))&&(methodFilter==='all'||e.method===methodFilter)&&(filter==='all'||g.id===filter));
  const summary=data.sessions.find((g:any)=>g.id===summaryId)||[...data.sessions].reverse().find((g:any)=>g.status==='closed')||data.sessions.at(-1);
  return <>
  <div className="stats">
   <StatCard icon={Users} label="Unpaid" value={unpaidRows.length} sub={`${money(unpaidTotal)} total`}/>
   <StatCard icon={Coins} label="Outstanding" value={money(unpaidTotal)} sub={`Across ${debtors.length} player${debtors.length===1?'':'s'}`}/>
   <StatCard icon={CircleCheck} label="Paid Today" value={money(paidToday.reduce((n:number,{e}:any)=>n+e.amount,0))} sub={`${paidToday.length} settlement${paidToday.length===1?'':'s'}`}/>
   {differenceCard}
  </div>
  <div className="grid-main">
   <section className="box"><div className="box-title"><h2>Settlements{rows.length>0&&<span className="count-pill">{rows.length} Unpaid</span>}</h2><div className="tools"><label className="filter">Show<select value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="all">All</option><option value="unpaid">Unpaid</option><option value="paid">Settled</option></select></label><label className="filter">Game<select value={gameFilter} onChange={e=>setGameFilter(e.target.value)}><option value="all">All Games</option>{games.map((g:any)=><option key={g.id} value={g.id}>{gameLabel(g)}</option>)}</select></label>{rows.length>0&&<button className="btn small" onClick={()=>remind([...new Set(rows.map((t:any)=>t.from))] as string[])}><BellRing size={14}/>Remind all</button>}</div></div>
    <div className="scroll"><table><thead><tr><th>From</th><th>To</th><th>Game</th><th className="num">Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>{rows.map((t:any)=><tr key={`${t.game.id}-${t.from}-${t.to}-${t.method||''}`}><td><span className="who">{who(t.from,false)}<ArrowRight className="arrow" size={15}/></span></td><td>{who(t.to,false)}</td><td><a {...link('settlements',t.game.id)}>{t.game.title}</a><span className="sub-line">{formatDate(gameDate(t.game))}</span></td><td className="num amt">{money(t.amount)}{t.method&&<small className="sub-line">cash</small>}</td><td><Pill kind="unpaid">Unpaid</Pill></td><td className="act"><span className="btn-row"><button className="btn small settle" onClick={()=>settle(t.game.id,t.from,t.to,t.amount,t.method)}>Settle</button><button className="dots" title={`Remind ${person(t.from)}`} aria-label={`Remind ${person(t.from)}`} onClick={()=>remind([t.from])}><BellRing size={15}/></button></span></td></tr>)}{doneRows.map(({e,g}:any)=><tr key={e.id} className="done"><td><span className="who">{who(e.from,false)}<ArrowRight className="arrow" size={15}/></span></td><td>{who(e.to,false)}</td><td><a {...link('settlements',g.id)}>{g.title}</a><span className="sub-line">{formatDate(gameDate(g))}</span></td><td className="num amt">{money(e.amount)}</td><td><Pill kind="paid"><Check size={12}/>Settled</Pill><small className="sub-line">{formatDate(e.confirmedAt||e.at)}</small></td><td className="act"><button className="link" onClick={()=>open('void',{entryId:e.id,sessionId:g.id})}>Undo</button></td></tr>)}{!rows.length&&!doneRows.length&&<tr><td className="empty" colSpan={6}>{statusFilter==='paid'?'Nothing settled yet.':'Nobody owes anything.'}</td></tr>}</tbody></table></div>
    {rows.length>0&&<p className="hint" style={{padding:'0 20px'}}>Players with an unpaid balance can’t buy in until it’s settled.</p>}
   </section>
   <GameSummary game={summary} picker action={summary&&<button className="btn green wide" onClick={()=>selectGame(summary.id,'settlements')}><Landmark size={18}/>Reconcile Game</button>}/>
  </div>
  <section className="box"><div className="box-title"><h2>Payment History</h2><div className="tools">
   <label className="search-field"><Search size={16}/><input aria-label="Search players" placeholder="Search players…" value={historyQuery} onChange={e=>setHistoryQuery(e.target.value)}/></label>
   <label className="filter">Game<select value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">All Games</option>{[...data.sessions].reverse().map((g:any)=><option key={g.id} value={g.id}>{g.title}</option>)}</select></label>
   <label className="filter">Method<select value={methodFilter} onChange={e=>setMethodFilter(e.target.value)}><option value="all">All Methods</option>{METHODS.map(m=><option key={m}>{m}</option>)}</select></label>
  </div></div><div className="scroll"><table><thead><tr><th>Date</th><th>Game / Session</th><th>From</th><th>To</th><th className="num">Amount</th><th>Method</th><th>Status</th></tr></thead><tbody>
   {history.length?history.slice(0,50).map(({e,g}:any)=><tr key={e.id}><td>{formatDate(e.at)} <span className="muted">&nbsp;{formatTime(e.at)}</span></td><td><a {...link('settlements',g.id)}>{g.title}</a></td><td><span className="who">{who(e.from)}<ArrowRight className="arrow" size={14}/></span></td><td>{who(e.to)}</td><td className="num amt">{money(e.amount)}</td><td><Method method={e.method}/></td><td>{e.status==='paid'?<Pill kind="paid">Paid</Pill>:<Pill kind="pending">Pending</Pill>}</td></tr>):<tr><td className="empty" colSpan={7}>No payments recorded.</td></tr>}
  </tbody></table></div></section></>;
 }

 function Players(){const profiles=playerProfiles(data),people=profiles.filter((p:any)=>p.name.toLowerCase().includes(query.toLowerCase())).sort((a:any,b:any)=>b.net-a.net||b.games-a.games),played=profiles.filter((p:any)=>p.games),top=[...played].sort((a:any,b:any)=>b.net-a.net)[0],regular=[...played].sort((a:any,b:any)=>b.games-a.games)[0];return <>
  <div className="stats">
   <StatCard icon={Users} label="Players" value={data.players.length} sub={`${played.length} with closed games`}/>
   <StatCard icon={Trophy} label="Top Winner" value={top?top.name:'—'} sub={top?<span className="positive">{signedMoney(top.net)}</span>:'No closed games'}/>
   <StatCard icon={Layers} label="Most Games" value={regular?regular.name:'—'} sub={regular?`${regular.games} games`:'No closed games'}/>
   <StatCard icon={Coins} label="Total Bought In" value={money(profiles.reduce((n:number,p:any)=>n+p.bought,0))} sub="Closed games"/>
  </div>
  <section className="box"><div className="box-title"><h2>Players</h2><div className="tools"><label className="search-field"><Search size={16}/><input aria-label="Find a player" placeholder="Search players…" value={query} onChange={e=>setQuery(e.target.value)}/></label><button className="btn gold" onClick={()=>open('player')}><UserPlus size={16}/>Add player</button></div></div>
  <div className="scroll"><table><thead><tr><th>#</th><th>Player</th><th className="num">Games</th><th className="num">Net</th><th className="num">Won</th><th className="num">Best</th><th className="num">Worst</th><th className="num">Streak</th><th className="num">Bought In</th>{privateProfiles.ready&&<th>Email</th>}<th/></tr></thead><tbody>
   {people.length?people.map((p:any,i:number)=>{const c=privateProfiles.ready?privateProfiles.contacts[p.id]:null;return <tr key={p.id}><td>{i+1}</td><td><Who name={p.name} index={indexOf(p.id)}/></td><td className="num">{p.games}</td><td className={`num ${tone(p.net)}`}><b>{p.games?signedMoney(p.net):'—'}</b></td><td className="num">{p.games?`${p.wins}/${p.games}`:'—'}</td><td className="num">{p.games?signedMoney(p.best):'—'}</td><td className="num">{p.games?signedMoney(p.worst):'—'}</td><td className="num">{p.streak?`${Math.abs(p.streak)}${p.streak>0?'W':'L'}`:'—'}</td><td className="num amt">{money(p.bought)}</td>{privateProfiles.ready&&<td className="muted">{c?.email?<>{c.email}{c.enabled===false&&' (off)'}</>:'—'}</td>}<td className="act"><button className="btn small settle" onClick={()=>open('edit-player',{playerId:p.id,name:p.name})}>Edit</button></td></tr>;}):<tr><td className="empty" colSpan={11}>{query?'No match.':'No players yet.'}</td></tr>}
  </tbody></table></div></section></>;}

 function Settings(){return <><div className="columns" style={{marginBottom:18}}><section className="box"><div className="box-title"><h2>Sync</h2></div><table className="facts"><tbody><tr><th>Status</th><td className={online?'positive':'negative'}>{syncLabel}</td></tr><tr><th>Last cloud save</th><td>{updatedAt?new Date(updatedAt).toLocaleString():'—'}</td></tr><tr><th>Editing</th><td>{editor?'Unlocked':'View only'}</td></tr><tr><th>Background video</th><td><button className="link" onClick={()=>setMotion(v=>!v)}>{motion?'Playing · pause':'Paused · play'}</button></td></tr></tbody></table>{!online&&<div className="box-body"><button className="btn" onClick={()=>retry()}><RotateCcw size={15}/>Retry</button></div>}</section>
  <section className="box"><div className="box-title"><h2>Backups</h2></div><div className="box-body btn-row"><button className="btn gold" onClick={exportJSON}><Download size={16}/>Download JSON backup</button><button className="btn" disabled={!s} onClick={exportCSV}><Download size={16}/>Export current game (CSV)</button><button className="btn" onClick={()=>fileRef.current?.click()}><Upload size={16}/>Import backup</button></div></section></div>
  <EmailSettings editor={editor} unlock={()=>open('unlock')}/></>;}

 const modalTitles:Record<string,string>={email:'Resend results',session:'New game',player:'Add player','edit-player':'Edit player',buyin:'Record buy-in',cashout:'Record cash-out',transfer:'Record settlement',close:'Close game',notes:'Session notes',share:'Share',void:'Void entry',allocate:'Assign difference',unlock:'Unlock editing'};
 const playerOptions=(withBank=false,blockDebtors=false)=> <>{withBank&&<option value={BANK_ID}>{person(BANK_ID)}</option>}{data.players.map((p:any)=>{const owes=blockDebtors&&debts.get(p.id);return <option value={p.id} key={p.id} disabled={!!owes}>{p.name}{owes?` (owes ${money(owes.reduce((n:number,d:any)=>n+d.amount,0))})`:''}</option>;})}</>;
 const gamePage=['game','activity','settlements'].includes(page);
 const nav=[{id:'overview',label:'Dashboard',active:page==='overview',href:'/',go:()=>navigate('overview')},{id:'history',label:'Games',active:page==='history',href:'/games',go:()=>navigate('history')},{id:'live',label:'Live Session',active:gamePage,href:routePath('game',(liveGame||data.sessions.at(-1))?.id||''),go:()=>{const g=liveGame||data.sessions.at(-1);if(g)selectGame(g.id);else navigate('history');}},{id:'owed',label:'Settlements',active:page==='owed',href:'/settlements',go:()=>navigate('owed'),count:debtors.length},{id:'players',label:'Players',active:page==='players',href:'/players',go:()=>navigate('players')}];
 const content=!ready&&!data.sessions.length?<div className="loading"><LoaderCircle className="spin" size={26} style={{animation:'spin 1s linear infinite'}}/><p>Loading games…</p></div>:page==='missing'||(ready&&sessionId&&!s)||(gamePage&&!s)?<section className="box"><p className="empty-note">Game or page not found. <a className="link" {...link('history')}>View all games</a></p></section>:page==='overview'?DashboardPage():page==='game'?LiveSession():page==='players'?Players():page==='activity'?ActivityPage():page==='owed'?SettlementsPage():page==='settlements'?GameSettlements():page==='history'?GamesPage():page==='music'?<MusicPanel music={music} session={s} editor={editor} unlock={()=>open('unlock')}/>:Settings();
 return <div className="app-shell" data-motion={motion?'on':'off'}>{intro&&<Intro onDone={()=>setIntro(false)}/>}<div className="app-atmosphere" aria-hidden="true"><video ref={videoRef} className="room-background" src="/room-loop.mp4" poster="/room.jpg" autoPlay={motion} muted loop playsInline preload="auto"/><div className="app-background-overlay"/></div><div className="app-content"><a className="skip-link" href="#main">Skip to content</a>
 <header className="topnav"><a className="brand" href="/" onClick={e=>{e.preventDefault();navigate('overview');}}><Spade size={34} fill="currentColor" strokeWidth={1}/><span>OpenStax <b>Poker</b></span></a>
  <nav className="mainnav" aria-label="Main navigation">{nav.map(n=><a key={n.id} href={n.href} className={n.active?'active':''} aria-current={n.active?'page':undefined} onClick={e=>{if(e.metaKey||e.ctrlKey)return;e.preventDefault();n.go();}}>{n.label}{!!n.count&&<span className="nav-count">{n.count}</span>}</a>)}</nav>
  <div className="top-right">
   {liveGame&&<a className="live-chip" title={liveGame.title} {...link('game',liveGame.id)}><i className="dot"/><span><b>Live Game</b><small>{participants(liveGame).length} players · {duration(liveGame)}</small></span></a>}
   {!allSaved&&<button className={`icon-btn ${online?'busy':''}`} title={syncLabel} aria-label={syncLabel} onClick={()=>navigate('settings')}>{online?<LoaderCircle size={18}/>:<CloudOff size={18}/>}</button>}
   <button className={`icon-btn ${page==='music'?'on':''}`} title="Music" aria-label="Music" onClick={()=>navigate('music')}><Headphones size={18}/>{music.room?.isPlaying&&<i className="badge-dot" style={{background:'var(--green)'}}/>}</button>
   <button className={`icon-btn ${page==='settings'?'on':''}`} title="Settings" aria-label="Settings" onClick={()=>navigate('settings')}><SettingsIcon size={18}/></button>
   <button className="icon-btn" title="Share" aria-label="Share this page" onClick={()=>open('share')}><Share2 size={18}/></button>
   <button className={`icon-btn ${editor?'on':''}`} title={editor?'Editing unlocked · click to lock':'Unlock editing'} aria-label={editor?'Lock editing':'Unlock editing'} onClick={()=>editor?lock():open('unlock')}>{editor?<LockKeyholeOpen size={18}/>:<LockKeyhole size={18}/>}</button>
  </div>
 </header>
 <main id="main" className={`page ${page==='overview'||page==='game'?'fit-page':''}`}>
  {!online&&<div className="notice" role="status"><CloudOff size={18}/><span>{pending?'Offline. Your changes are saved on this device and will sync when you reconnect.':'Offline. Showing the last saved table.'} <button className="link" onClick={()=>retry()}>Retry</button></span></div>}
  {error&&<div className="alert" role="alert"><span>{error} The rejected change is kept on this device.</span><button className="dots" aria-label="Dismiss error" onClick={clearError}><X size={15}/></button></div>}
  {(page==='music'||page==='settings')&&<div className="game-bar"><div className="game-chip"><h1>{page==='music'?'Music':'Settings'}</h1></div></div>}
  {content}
 </main></div>
 <input type="file" ref={fileRef} accept=".json,application/json" hidden onChange={e=>{const file=e.target.files?.[0];if(file)void importFile(file);e.target.value='';}}/>
 {notice&&<div className="toast" role="status">{notice.error?<AlertCircle size={17} style={{color:'var(--red)'}}/>:<CheckCircle2 size={17}/>}{notice.text}<button onClick={()=>setNotice(null)} aria-label="Dismiss notification"><X size={14}/></button></div>}
 <dialog ref={dialogRef} onCancel={()=>setModal('')} onClick={e=>{if(e.target===e.currentTarget)setModal('');}} aria-labelledby="modal-title"><div className="dialog-title"><h2 id="modal-title">{modalTitles[modal]}</h2><button type="button" aria-label="Close dialog" onClick={()=>setModal('')}><X size={20}/></button></div><div className="dialog-body">
 {modal==='share'?<><div className="share-link"><input readOnly aria-label="Link" value={typeof window!=='undefined'?window.location.origin+window.location.pathname:''} onFocus={e=>e.currentTarget.select()}/><button className="btn gold" onClick={async()=>{try{await navigator.clipboard.writeText(window.location.origin+window.location.pathname);toast('Link copied.');setModal('');}catch{setFormError('Could not copy. Select the link and copy it.');}}}><Copy size={15}/>Copy</button></div><p className="hint" style={{marginTop:12}}>Anyone with the link can view. Editing needs the passcode.</p>{formError&&<p className="form-error">{formError}</p>}</>:<form key={modal+JSON.stringify(preset)+(modal==='edit-player'||modal==='email'?String(privateProfiles.ready):'')} onSubmit={submit}>
 {modal==='unlock'&&<label>Passcode<input name="passcode" type="password" autoComplete="current-password" required autoFocus/></label>}
 {modal==='email'&&(!privateProfiles.ready?<p className="hint">{privateProfiles.error||'Loading email addresses…'}</p>:<div className="pick-list">{ids.map((id:any)=>{const c=privateProfiles.contacts[id],ok=!!c?.email&&c.enabled!==false;return <label key={id} className={ok?'':'disabled'}><input type="checkbox" name="playerIds" value={id} defaultChecked={ok} disabled={!ok}/><Avatar name={person(id)} index={indexOf(id)} small/><span><b>{person(id)}</b><small>{c?.email?(c.enabled===false?'Updates off':c.email):'No email'}</small></span>{!c?.email&&<button type="button" className="link" onClick={()=>open('edit-player',{playerId:id,name:person(id)})}>Add</button>}</label>;})}</div>)}
 {modal==='session'&&<><label>Game name<input name="title" required maxLength={100} autoFocus defaultValue="Poker night"/></label><label>Type<select name="mode" defaultValue="decentralized"><option value="decentralized">Pay at end</option><option value="centralized">Banker collects</option></select></label></>}
 {(modal==='player'||modal==='edit-player')&&<><label>Name<input name="name" required maxLength={100} autoFocus defaultValue={preset.name||''}/></label><label>Email (optional)<input name="email" type="email" autoComplete="email" maxLength={254} defaultValue={modal==='edit-player'?privateProfiles.contacts[preset.playerId]?.email||'':''} disabled={modal==='edit-player'&&!privateProfiles.ready}/></label><label className="check"><input type="checkbox" name="emailEnabled" defaultChecked={modal==='player'||privateProfiles.contacts[preset.playerId]?.enabled!==false}/>Send email updates</label>{modal==='edit-player'&&!privateProfiles.ready&&<p className="hint">{privateProfiles.error||'Loading email…'}</p>}</>}
 {(modal==='buyin'||modal==='cashout')&&<><label>Player<select name="playerId" required value={selectedPlayer} onChange={e=>setSelectedPlayer(e.target.value)}><option value="" disabled>Choose a player</option>{playerOptions(false,modal==='buyin')}{modal==='buyin'&&<option value="__new">+ New player</option>}</select></label>{selectedPlayer==='__new'&&<label>New player’s name<input name="newName" required maxLength={100}/></label>}<label>{modal==='buyin'?'Amount':'Final chips'}<input name="amount" type="number" inputMode="decimal" min={modal==='cashout'?'0':'0.01'} step="0.01" required defaultValue={preset.amount||''} placeholder={modal==='cashout'?'0 if busted':'$'}/></label>{modal==='buyin'&&<div className="quick">{[10,20,40,100].map(n=><button className="btn small" key={n} type="button" onClick={e=>{const input=e.currentTarget.closest('form')?.querySelector<HTMLInputElement>('[name="amount"]');if(input){input.value=n.toFixed(2);input.focus();}}}>${n}</button>)}</div>}{modal==='buyin'&&s?.mode==='centralized'&&<><label>Method<select name="method">{METHODS.map(m=><option key={m}>{m}</option>)}</select></label><label className="check"><input name="received" type="checkbox" defaultChecked/>Banker has the money</label></>}<label>Note (optional)<input name="note" maxLength={150}/></label></>}
 {modal==='transfer'&&<><label>From<select name="from" defaultValue={preset.from||BANK_ID}>{playerOptions(true)}</select></label><label>To<select name="to" defaultValue={preset.to||data.players[0]?.id}>{playerOptions(true)}</select></label><label>Amount<input name="amount" type="number" min="0.01" step="0.01" inputMode="decimal" required defaultValue={preset.amount||''}/></label><label>Method<select name="method">{METHODS.map(m=><option key={m}>{m}</option>)}</select></label><label className="check"><input name="paid" type="checkbox"/>Confirmed paid</label><label>Note (optional)<input name="note" maxLength={150}/></label></>}
 {modal==='close'&&<><table className="facts" style={{marginBottom:14}}><tbody><tr><th>Total buy-ins</th><td>{money(st?.totalIn||0)}</td></tr><tr><th>Final chips</th><td>{money(st?.totalOut||0)}</td></tr><tr><th>Difference</th><td className={st?.unresolved?'negative':''}>{money(st?.unresolved||0)}</td></tr></tbody></table>{ids.some((id:any)=>playerStats(s,id).open)&&<p className="form-error">No cash-out yet for {ids.filter((id:any)=>playerStats(s,id).open).map((id:any)=>person(id)).join(', ')}.</p>}</>}
 {modal==='notes'&&<label>Notes<textarea name="notes" rows={6} maxLength={5000} defaultValue={s?.notes||''} autoFocus/></label>}
 {modal==='void'&&<><p className="hint">The entry stays in the register, crossed out.</p><label>Reason<input name="note" maxLength={150} autoFocus/></label></>}
 {modal==='allocate'&&<><p className="hint">Remaining difference: {money(st?.unresolved||0)}</p><label>Player<select name="playerId" required><option value="">Choose a player</option>{ids.map((id:any)=><option key={id} value={id}>{person(id)}</option>)}</select></label><label>Amount<input name="amount" type="number" min="0.01" step="0.01" max={Math.abs(st?.unresolved||0)/100} required/></label><label>Agreed reason<input name="note" required maxLength={150}/></label></>}
 {formError&&<p className="form-error" role="alert">{formError}</p>}
 <div className="dialog-actions"><button className="btn" type="button" onClick={()=>setModal('')}>Cancel</button><button className={`btn ${modal==='void'?'danger':'gold'}`} type="submit">{modal==='unlock'?'Unlock':modal==='email'?'Send':modal==='session'?'Create game':modal==='player'?'Add player':modal==='buyin'||modal==='cashout'||modal==='transfer'?'Record':modal==='close'?'Close game':modal==='void'?'Void entry':'Save'}</button></div></form>}
 </div></dialog></div>;
}
